import type { FieldIR, ModelIR, SpecIR } from "@smithable/core";
import { camel, kebab } from "@smithable/core";

// The formula tree comes from @smithable/core's parser; only its shape is needed here.
type Expr = NonNullable<FieldIR["formula"]>;

const HEADER =
  "// Generated by Smithable from smithable.yml. Do not edit: this file is overwritten on every change.\n";

export const formulasName = (model: ModelIR) => `${camel(model.name)}Formulas`;
export const defaultsName = (model: ModelIR) => `${camel(model.name)}Defaults`;
export const withFormulasName = (model: ModelIR) => `with${model.name}Formulas`;
export const formulasModule = (model: ModelIR) => `./${kebab(model.name)}.formulas`;

export function hasFormulas(model: ModelIR): boolean {
  return model.fields.some((f) => f.formula || f.defaultFormula);
}

/** The TypeScript type a field's value has in a record. */
function tsType(field: FieldIR): string {
  if (field.type.kind !== "scalar") return "string";
  switch (field.type.name) {
    case "int":
    case "decimal":
    case "money":
      return "number";
    case "bool":
      return "boolean";
    default:
      return "string";
  }
}

const isMoney = (field: FieldIR) => field.type.kind === "scalar" && field.type.name === "money";

/**
 * Compiles checked formulas to TypeScript that works on records as stored: money in cents.
 * Formulas themselves work in whole currency units, like a spreadsheet.
 */
export function formulasModuleSource(model: ModelIR, ir: SpecIR): string {
  const { compile, stored, imports } = formulaCompiler(model, ir, model);

  const computed = model.fields.filter((f) => f.formula);
  const defaults = model.fields.filter((f) => f.defaultFormula);
  // A formula that reads no field, like TODAY(), gets an "_r" parameter (unused on purpose).
  const entry = (f: FieldIR, expr: Expr) => {
    const code = stored(f, compile(expr, model, "r"));
    const param = /\br\b/.test(code) ? "r" : "_r";
    return `  ${f.name}: (${param}: Row): ${tsType(f)} => ${code},`;
  };
  const computedEntries = computed.map((f) => entry(f, f.formula as Expr));
  const defaultEntries = defaults.map((f) => entry(f, f.defaultFormula as Expr));
  const withType = computed.length
    ? `T & { ${computed.map((f) => `${f.name}: ${tsType(f)}`).join("; ")} }`
    : "T";
  const withBody = computed.length
    ? `{ ...row, ${computed.map((f) => `${f.name}: ${formulasName(model)}.${f.name}(row)`).join(", ")} }`
    : "row";

  // The formula library only when a formula uses it (a calculator's may not).
  const usesF = [...computedEntries, ...defaultEntries].some((e) => e.includes("F."));
  return `${HEADER}${usesF ? 'import { F } from "#/kit/formula";\n' : ""}${[...imports].map((m) => `import { ${formulasName(m)} } from "${formulasModule(m)}";\n`).join("")}
type Row = Record<string, unknown>;

/** Computed fields of ${model.name}, on records as stored (money in cents). */
export const ${formulasName(model)} = {
${computedEntries.join("\n")}
};

/** Values suggested when a ${model.name} is created. */
export const ${defaultsName(model)} = {
${defaultEntries.join("\n")}
};

/** The record with its computed fields. */
export function ${withFormulasName(model)}<T extends Row>(row: T): ${withType} {
  return ${withBody};
}
`;
}

/** A Vitest test per example: the formula must give the expected value. */
export function formulasTestSource(model: ModelIR): string | undefined {
  const cases = model.fields.flatMap((field) =>
    (field.examples ?? []).map((example) => ({ field, example })),
  );
  if (cases.length === 0) return undefined;
  const inCents = (name: string, value: unknown) => {
    const f = model.fields.find((x) => x.name === name);
    return f && isMoney(f) && typeof value === "number" ? Math.round(value * 100) : value;
  };
  const tests = cases.map(({ field, example }) => {
    const input = Object.entries(example.input).map(
      ([k, v]) => `${k}: ${JSON.stringify(inCents(k, v))}`,
    );
    const title = Object.entries(example.input)
      .map(([k, v]) => `${k} ${v}`)
      .join(", ");
    const expected = inCents(field.name, example.expected);
    return `  test(${JSON.stringify(`${title} gives ${example.expected}`)}, () => {
    expect(${formulasName(model)}.${field.name}({ ${input.join(", ")} })).toBe(${JSON.stringify(expected)});
  });`;
  });
  const byField = [...new Set(cases.map((c) => c.field.name))].map(
    (name) =>
      `describe(${JSON.stringify(`${model.name}.${name}`)}, () => {\n${tests.filter((_, i) => cases[i]?.field.name === name).join("\n\n")}\n});`,
  );
  return `${HEADER}// The examples given for ${model.name}'s formulas: each must give the expected value.
import { describe, expect, test } from "vitest";
import { ${formulasName(model)} } from "${formulasModule(model)}";

${byField.join("\n\n")}
`;
}

/** Lists that aggregates in the model's formulas read, e.g. "lines" for SUM(lines.amount). */
export function aggregatedLists(model: ModelIR): string[] {
  const found = new Set<string>();
  const visit = (e: unknown): void => {
    if (!e || typeof e !== "object") return;
    const node = e as { kind?: string; list?: string };
    if (node.kind === "aggregate" && node.list) found.add(node.list);
    for (const value of Object.values(e)) visit(value);
  };
  for (const field of model.fields) visit(field.formula);
  return [...found];
}

/**
 * Compiles formulas on records of `model` as stored. Computed fields of other models than
 * `home` (the module the code goes in, if it is a model's formulas module) are read through
 * their formulas modules, which `imports` collects.
 */
export function formulaCompiler(model: ModelIR, ir: SpecIR, home?: ModelIR) {
  const imports = new Set<ModelIR>();
  let depth = 0;

  const modelNamed = (name: string) => ir.models.find((m) => m.name === name) as ModelIR;

  /** A field of a record in formula units. */
  const fieldValue = (owner: ModelIR, name: string, row: string): string => {
    const field = owner.fields.find((f) => f.name === name) as FieldIR;
    // A computed field is read through its formula; another model's formulas are imported.
    if (field.formula && owner !== home) imports.add(owner);
    const raw = field.formula ? `${formulasName(owner)}.${name}(${row})` : `${row}.${name}`;
    if (field.type.kind === "choice") return `F.t(${raw})`;
    if (field.type.kind !== "scalar") return raw;
    switch (field.type.name) {
      case "money":
        return `F.fromCents(${raw})`;
      case "int":
      case "decimal":
        return `F.n(${raw})`;
      case "bool":
        return `Boolean(${raw})`;
      case "date":
        return `F.d(${raw})`;
      case "datetime":
        return raw;
      default:
        return `F.t(${raw})`;
    }
  };

  const compile = (e: Expr, owner: ModelIR, row: string): string => {
    switch (e.kind) {
      case "number":
        return String(e.value);
      case "text":
        return JSON.stringify(e.value);
      case "bool":
        return String(e.value);
      case "field":
        return fieldValue(owner, e.name, row);
      case "unary":
        return `-${compile(e.operand, owner, row)}`;
      case "binary": {
        const l = compile(e.left, owner, row);
        const r = compile(e.right, owner, row);
        if (e.op === "&") return `(F.t(${l}) + F.t(${r}))`;
        if (["+", "-", "*", "/"].includes(e.op)) return `(${l} ${e.op} ${r})`;
        return `F.compare(${JSON.stringify(e.op)}, ${l}, ${r})`;
      }
      case "call": {
        const a = e.args.map((arg) => compile(arg, owner, row));
        switch (e.name) {
          case "IF":
            return `(${a[0]} ? ${a[1]} : ${a[2]})`;
          case "AND":
            return `(${a.join(" && ")})`;
          case "OR":
            return `(${a.join(" || ")})`;
          case "NOT":
            return `!${a[0]}`;
          case "ROUND":
            return `F.ROUND(${a.join(", ")})`;
          case "ABS":
            return `Math.abs(${a[0]})`;
          case "PMT":
            return `F.PMT(${a.join(", ")})`;
          case "MIN":
            return `Math.min(${a.join(", ")})`;
          case "MAX":
            return `Math.max(${a.join(", ")})`;
          case "TODAY":
            return "F.TODAY()";
          case "NOW":
            return "F.NOW()";
          case "DATEADD":
            return `F.DATEADD(${a.join(", ")})`;
          case "DAYS":
            return `F.DAYS(${a.join(", ")})`;
          case "CONCAT":
            return `(${a.map((x) => `F.t(${x})`).join(" + ")})`;
        }
        throw new Error("Unknown function");
      }
      case "aggregate": {
        const listField = owner.fields.find((f) => f.name === e.list) as FieldIR;
        const target = modelNamed((listField.type as { model: string }).model);
        const items = `F.list(${row}.${e.list})`;
        if (e.name === "COUNT") return `${items}.length`;
        depth++;
        const item = `x${depth}`;
        const value = fieldValue(target, e.field as string, item);
        const result =
          e.name === "LAST" || e.name === "FIRST"
            ? `(F.${e.name}(${items}, (${item}) => ${value})${emptyOf(target, e.field as string)})`
            : e.name === "COUNTIF"
              ? `${items}.filter((${item}) => F.compare("=", ${value}, ${compile(e.value as Expr, owner, row)})).length`
              : `F.${e.name}(${items}.map((${item}) => ${value}))`;
        depth--;
        return result;
      }
    }
  };

  /** What LAST or FIRST of an empty list gives, as the field's kind has it: "", 0 or false. */
  const emptyOf = (target: ModelIR, name: string): string => {
    const field = target.fields.find((f) => f.name === name) as FieldIR;
    if (field.type.kind === "choice") return ' ?? ""';
    if (field.type.kind !== "scalar") return "";
    if (["int", "decimal", "money"].includes(field.type.name)) return " ?? 0";
    if (field.type.name === "bool") return " ?? false";
    if (["date", "datetime", "picture", "pictures", "file", "files"].includes(field.type.name))
      return "";
    return ' ?? ""';
  };

  /** A computed value converted back to stored units. */
  const stored = (field: FieldIR, code: string) => (isMoney(field) ? `F.toCents(${code})` : code);

  return { compile, stored, imports };
}
